<?php $first=true;foreach($groups as $group=>$fields): ?><details class="os-content-group" <?= $first?'open':''; ?> data-group="<?= htmlspecialchars(mb_strtolower($group)); ?>"><summary><?= htmlspecialchars($group); ?><span>+</span></summary><div class="os-content-fields"><?php foreach($fields as $key=>$field):$rawValue=(string)$content_values[$key];$value=$rawValue;$default=$field['default'];if($field['type']==='image'){if($value!==''&&!preg_match('#^https?://#i',$value))$value=base_url($value);if($default!==''&&!preg_match('#^https?://#i',$default))$default=base_url($default);} ?>
<div class="os-content-field" data-search="<?= htmlspecialchars(mb_strtolower($group.' '.$field['label'].' '.$value),ENT_QUOTES); ?>"><label for="content-<?= $key; ?>"><?= (!$content_is_building&&$key==='shop_label')?'Shop page name (e.g. Garden shop, Shop or Our range)':((!$content_is_building&&$key==='menu_shop')?'Shop navigation label':htmlspecialchars($field['label'])); ?><button type="button" class="os-content-reset" data-reset="<?= $key; ?>">Use default</button></label>
<?php if($field['type']==='radio'): ?>
<div id="content-<?= $key; ?>" data-default="<?= htmlspecialchars($default,ENT_QUOTES); ?>"><?php foreach($field['options'] as $option=>$label): ?><label style="display:flex;align-items:flex-start;gap:8px;margin:12px 0"><input type="radio" name="content[<?= $key; ?>]" value="<?= htmlspecialchars($option,ENT_QUOTES); ?>" <?= $value===$option?'checked':''; ?>><?= htmlspecialchars($label); ?></label><?php endforeach; ?></div>
<?php elseif($field['type']==='textarea'): ?><textarea class="mp-form-control" id="content-<?= $key; ?>" name="content[<?= $key; ?>]" rows="3" maxlength="3000" data-default="<?= htmlspecialchars($default,ENT_QUOTES); ?>"><?= htmlspecialchars($value); ?></textarea><?php else: ?><input class="mp-form-control" id="content-<?= $key; ?>" name="content[<?= $key; ?>]" type="<?= $field['type']==='image'?'url':'text'; ?>" maxlength="<?= $field['type']==='image'?'1500':'500'; ?>" value="<?= htmlspecialchars($value,ENT_QUOTES); ?>" data-default="<?= htmlspecialchars($default,ENT_QUOTES); ?>"><?php endif; ?>
<?php if($field['type']==='image'): ?><?php if($rawValue!==''): ?><img class="os-content-image" src="<?= htmlspecialchars($value,ENT_QUOTES); ?>" alt="Current editorial photo"><?php endif; ?><label for="upload-<?= $key; ?>">Or upload a replacement photo</label><input class="mp-form-control" type="file" id="upload-<?= $key; ?>" name="theme_image_<?= $key; ?>" accept="image/jpeg,image/png,image/webp,image/avif,.avif"><div class="mp-form-hint">JPG, PNG, WebP or AVIF, up to 3 MB. A new upload takes priority over the URL.</div><?php endif; ?></div>
<?php endforeach; ?></div></details><?php $first=false;endforeach; ?></div><div class="os-content-actions"><button type="submit" class="mp-btn-primary" id="os-content-save">Save storefront content</button><span class="os-content-feedback" id="os-content-feedback" role="status"></span></div></form>
<script>
(function(){var form=document.getElementById('os-content-form'),search=document.getElementById('os-content-search');search.addEventListener('input',function(){var query=search.value.trim().toLowerCase();document.querySelectorAll('.os-content-group').forEach(function(group){var visible=0;group.querySelectorAll('.os-content-field').forEach(function(field){field.hidden=!!query&&field.dataset.search.indexOf(query)===-1;if(!field.hidden)visible++;});group.hidden=visible===0;if(query&&visible)group.open=true;});});document.querySelectorAll('[data-reset]').forEach(function(button){button.addEventListener('click',function(){var input=document.getElementById('content-'+button.dataset.reset),radios=input.querySelectorAll('input[type=radio]');if(radios.length){radios.forEach(function(radio){radio.checked=radio.value===input.dataset.default;});}else{input.value=input.dataset.default;}var file=document.getElementById('upload-'+button.dataset.reset);if(file)file.value='';});});form.addEventListener('submit',function(event){event.preventDefault();var button=document.getElementById('os-content-save'),message=document.getElementById('os-content-feedback');button.disabled=true;message.textContent='Saving…';fetch(<?= json_encode(base_url('online_store/save_theme_content')); ?>,{method:'POST',body:new FormData(form)}).then(function(response){return response.json();}).then(function(result){if(result.csrf_hash)form.querySelector('[data-content-csrf]').value=result.csrf_hash;message.textContent=result.message||'Please try again.';if(result.status==='success')setTimeout(function(){window.location.reload();},500);}).catch(function(){message.textContent='Could not connect. Your edits are still here; please try again.';}).finally(function(){button.disabled=false;});});})();
</script>
